    finally { renameSync(parked, manifest); }
  }
  const extra = join(fixture, ENGINEERING_BASE, 'engineering-extra.json');
  try { writeFileSync(extra, '{}'); assert.match(denied().errors.join('\n'), /engineering evidence inventory/); }
